478		public void accept(ConsumerRecord<?, ?> record, @Nullable Consumer<?, ?> consumer, Exception exception) {
479			TopicPartition tp = this.destinationResolver.apply(record, exception);
480			if (tp == null) {
481				maybeThrow(record, exception);
482				this.logger.debug(() -> "Recovery of " + KafkaUtils.format(record)
483						+ " skipped because destination resolver returned null");
484				return;
485			}
486			if (this.skipSameTopicFatalExceptions
487					&& tp.topic().equals(record.topic())
488					&& !getExceptionMatcher().match(exception)) {
489				this.logger.error("Recovery of " + KafkaUtils.format(record)
490						+ " skipped because not retryable exception " + exception.toString()
491						+ " and the destination resolver routed back to the same topic");
492				return;
493			}
494			if (this.logRecoveryRecord) {
495				this.logger.info(exception, () -> "Recovery record " + KafkaUtils.format(record));
496			}
497			if (consumer != null && this.verifyPartition) {
498				tp = checkPartition(tp, consumer);
499			}
500			DeserializationException vDeserEx = SerializationUtils.getExceptionFromHeader(record,
501					KafkaUtils.VALUE_DESERIALIZER_EXCEPTION_HEADER, this.logger);
502			DeserializationException kDeserEx = SerializationUtils.getExceptionFromHeader(record,
503					KafkaUtils.KEY_DESERIALIZER_EXCEPTION_HEADER, this.logger);
504			Headers headers = new RecordHeaders(record.headers().toArray());
505			this.deadLetterRecordManager.addAndEnhanceHeaders(record, exception, vDeserEx, kDeserEx, headers);
506			ProducerRecord<Object, Object> outRecord = createProducerRecord(record, tp, headers,
507					kDeserEx == null ? null : kDeserEx.getData(), vDeserEx == null ? null : vDeserEx.getData());
508			KafkaOperations<?, ?> kafkaTemplate = this.templateResolver.apply(outRecord);
509			sendOrThrow(outRecord, (KafkaOperations<Object, Object>) kafkaTemplate, record);
510		}
