512		private void sendOrThrow(ProducerRecord<Object, Object> outRecord,
513				@Nullable KafkaOperations<Object, Object> kafkaTemplate, ConsumerRecord<?, ?> inRecord) {
514	
515			if (kafkaTemplate != null) {
516				send(outRecord, kafkaTemplate, inRecord);
517			}
518			else {
519				throw new IllegalArgumentException("No kafka template returned for record " + outRecord);
520			}
521		}
522	
523		private void maybeThrow(ConsumerRecord<?, ?> record, Exception exception) {
524			String message = String.format("No destination returned for record %s and exception %s. " +
525							"throwIfNoDestinationReturned: %s", KafkaUtils.format(record), exception,
526					this.throwIfNoDestinationReturned);
527			this.logger.warn(message);
528			if (this.throwIfNoDestinationReturned) {
529				throw new IllegalArgumentException(message);
530			}
531		}
