533		/**
534		 * Send the record.
535		 * @param outRecord the record.
536		 * @param kafkaTemplate the template.
537		 * @param inRecord the consumer record.
538		 * @since 2.7
539		 */
540		protected void send(ProducerRecord<Object, Object> outRecord, KafkaOperations<Object, Object> kafkaTemplate,
541				ConsumerRecord<?, ?> inRecord) {
542	
543			if (this.transactional && !kafkaTemplate.inTransaction() && !kafkaTemplate.isAllowNonTransactional()) {
544				kafkaTemplate.executeInTransaction(t -> {
545					publish(outRecord, t, inRecord);
546					return null;
547				});
548			}
549			else {
550				publish(outRecord, kafkaTemplate, inRecord);
551			}
552		}
