554		private TopicPartition checkPartition(TopicPartition tp, Consumer<?, ?> consumer) {
555			if (tp.partition() < 0) {
556				return tp;
557			}
558			try {
559				List<PartitionInfo> partitions = consumer.partitionsFor(tp.topic(), this.partitionInfoTimeout);
560				if (partitions == null) {
561					this.logger.debug(() -> "Could not obtain partition info for " + tp.topic());
562					return tp;
563				}
564				boolean anyMatch = partitions.stream().anyMatch(pi -> pi.partition() == tp.partition());
565				if (!anyMatch) {
566					this.logger.warn(() -> "Destination resolver returned non-existent partition " + tp
567							+ ", KafkaProducer will determine partition to use for this topic");
568					return new TopicPartition(tp.topic(), -1);
569				}
570				return tp;
571			}
572			catch (Exception ex) {
573				this.logger.debug(ex, () -> "Could not obtain partition info for " + tp.topic());
574				return tp;
575			}
576		}
