import org.apache.kafka.common.TopicPartition;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.kafka.listener.DeadLetterPublishingRecoverer;
import org.springframework.kafka.listener.DefaultErrorHandler;
import org.springframework.kafka.support.ExponentialBackOffWithMaxRetries;
import tools.jackson.core.JacksonException;

// Error handling for every @KafkaListener in this service. Spring Boot hands
// the single CommonErrorHandler bean to the listener container factory.
//
// A failing record is retried in place with a growing delay. Once the retries
// are used up, or when the failure can never be fixed by retrying, the record
// is copied unchanged to <topic>.DLT and the consumer moves on.
@Configuration
public class KafkaConfig {

    static final String DEAD_LETTER_SUFFIX = ".DLT";

    // 3 retries after the first attempt: 4 deliveries in total, 200 ms, 400 ms
    // and 800 ms apart, so the whole sequence is over in well under 5 seconds.
    static final int MAX_RETRIES = 3;
    static final long INITIAL_BACKOFF_MS = 200;
    static final double BACKOFF_MULTIPLIER = 2.0;
    static final long MAX_BACKOFF_MS = 1_000;

    @Bean
    public DefaultErrorHandler kafkaErrorHandler(KafkaTemplate<String, String> kafka) {
        DeadLetterPublishingRecoverer deadLetter = new DeadLetterPublishingRecoverer(kafka,
                (record, ex) -> new TopicPartition(record.topic() + DEAD_LETTER_SUFFIX,
